import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport '../providers/auth_providers.dart';\n\nclass TeacherLoginScreen extends ConsumerStatefulWidget {\n  const TeacherLoginScreen({Key? key}) : super(key: key);\n\n  @override\n  ConsumerState<TeacherLoginScreen> createState() => _TeacherLoginScreenState();\n}\n\nclass _TeacherLoginScreenState extends ConsumerState<TeacherLoginScreen> {\n  final _formKey = GlobalKey<FormState>();\n  final _emailController = TextEditingController();\n  final _passwordController = TextEditingController();\n  bool _isLoading = false;\n\n  @override\n  void dispose() {\n    _emailController.dispose();\n    _passwordController.dispose();\n    super.dispose();\n  }\n\n  Future<void> _login() async {\n    if (!_formKey.currentState!.validate()) return;\n\n    setState(() => _isLoading = true);\n\n    try {\n      final authService = ref.read(authServiceProvider);\n      await authService.loginTeacher(\n        _emailController.text.trim(),\n        _passwordController.text.trim(),\n      );\n\n      if (!mounted) return;\n      // Navigate to Teacher Dashboard\n      ScaffoldMessenger.of(context).showSnackBar(\n        const SnackBar(content: Text('تم تسجيل الدخول بنجاح')),\n      );\n      // Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => const TeacherDashboardScreen()));\n    } catch (e) {\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(content: Text(e.toString()), backgroundColor: Colors.red),\n      );\n    } finally {\n      if (mounted) {\n        setState(() => _isLoading = false);\n      }\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('دخول المعلمين'),\n      ),\n      body: Center(\n        child: SingleChildScrollView(\n          padding: const EdgeInsets.all(24.0),\n          child: Form(\n            key: _formKey,\n            child: Column(\n              mainAxisAlignment: MainAxisAlignment.center,\n              children: [\n                const Icon(Icons.admin_panel_settings, size: 80, color: Colors.blueGrey),\n                const SizedBox(height: 32),\n                TextFormField(\n                  controller: _emailController,\n                  keyboardType: TextInputType.emailAddress,\n                  decoration: const InputDecoration(\n                    labelText: 'البريد الإلكتروني',\n                    border: OutlineInputBorder(),\n                    prefixIcon: Icon(Icons.email),\n                  ),\n                  validator: (value) {\n                    if (value == null || value.trim().isEmpty || !value.contains('@')) {\n                      return 'يرجى إدخال بريد إلكتروني صحيح';\n                    }\n                    return null;\n                  },\n                ),\n                const SizedBox(height: 16),\n                TextFormField(\n                  controller: _passwordController,\n                  obscureText: true,\n                  decoration: const InputDecoration(\n                    labelText: 'كلمة المرور',\n                    border: OutlineInputBorder(),\n                    prefixIcon: Icon(Icons.lock),\n                  ),\n                  validator: (value) {\n                    if (value == null || value.isEmpty) {\n                      return 'يرجى إدخال كلمة المرور';\n                    }\n                    return null;\n                  },\n                ),\n                const SizedBox(height: 32),\n                SizedBox(\n                  width: double.infinity,\n                  height: 50,\n                  child: ElevatedButton(\n                    onPressed: _isLoading ? null : _login,\n                    style: ElevatedButton.styleFrom(backgroundColor: Colors.blueGrey),\n                    child: _isLoading\n                        ? const CircularProgressIndicator(color: Colors.white)\n                        : const Text('دخول', style: TextStyle(fontSize: 18)),\n                  ),\n                ),\n              ],\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n